<section class="settings-group"><h3>New product defaults</h3><x-input id="inventory-threshold" name="values[threshold]" type="number" label="Default low-stock threshold" :value="$values['threshold']" min="0" max="1000000" required /><p>Applies when creating new variants. Existing variants keep their individual thresholds.</p><x-setting-value label="Selling units" value="Piece, set, pair and bottle" /></section><section class="settings-group"><h3>Stock protection</h3><input type="hidden" name="values[allow_negative_stock]" value="0"><x-setting-value label="Negative stock" value="Blocked" /><x-setting-value label="Stock changes" value="Manager with a recorded reason" /><x-setting-value label="Product removal" value="Archive only · history is retained" /></section><section class="settings-group"><h3>Product images</h3><x-setting-select name="max_image_mb" label="Maximum upload size" :value="$values['max_image_mb']" :options="[1=>'1 MB',2=>'2 MB',3=>'3 MB',4=>'4 MB',5=>'5 MB']" /><x-setting-value label="Allowed images" value="JPG, PNG and WebP · up to 4096 × 4096 pixels" /></section>
